import assert from 'node:assert/strict';
import { resolvePermissions } from './src/resolve-permissions.js';

const rules = [
  { permission: 'read', allow: false },
  { permission: 'read', scope: 'team', allow: true },
  { permission: 'read', scope: 'team', allow: false },
];
const requested = ['read', { permission: 'read', scope: 'team' }, { permission: 'read', scope: 'other' }];
const rulesCopy = structuredClone(rules);
const requestedCopy = structuredClone(requested);
assert.deepEqual(resolvePermissions(rules, requested), [
  { permission: 'read', scope: undefined, allowed: false },
  { permission: 'read', scope: 'team', allowed: false },
  { permission: 'read', scope: 'other', allowed: false },
]);
assert.deepEqual(rules, rulesCopy);
assert.deepEqual(requested, requestedCopy);
for (const bad of [null, {}, [], { permission: 'x', allow: true, scope: null }]) assert.throws(() => resolvePermissions([bad], []), TypeError);
for (const bad of [null, 1, {}, { permission: 'x', scope: null }]) assert.throws(() => resolvePermissions([], [bad]), TypeError);
console.log('additional assertions passed');
EOF
